const raw = $json.body && typeof $json.body === 'object' ? $json.body : $json;
const expectedToken = String($vars?.FLUCTUATION_TAG_GATEWAY_TOKEN || '');
const suppliedToken = String($json.headers?.authorization || $json.headers?.Authorization || '').replace(/^Bearer\s+/i, '').trim();
if (expectedToken && suppliedToken !== expectedToken) throw new Error('Unauthorized fluctuation tag request');
const actions = new Set(['ensure', 'lookup', 'update']);
const tags = new Set(['一级', '二级', '三级']);
const text = (value, max, fallback = '') => String(value ?? '').replace(/\s+/g, ' ').trim().slice(0, max) || fallback;
const quote = (value) => '\'' + String(value ?? '').replace(/\\/g, String.fromCharCode(92, 92)).replace(/'/g, String.fromCharCode(92, 39)) + '\'';
const normalize = (value = {}) => ({
  country_name: text(value.country_name, 32, '未知国家'),
  dashboard_name: text(value.dashboard_name, 128, '未命名看板'),
  card_name: text(value.card_name, 128, '未命名卡片'),
  metric_name: text(value.metric_name, 128, '未命名指标'),
  dimension_name: text(value.dimension_name, 128, '无维度'),
  time_granularity: text(value.time_granularity, 8, 'day'),
  dashboard_url: text(value.dashboard_url, 255),
});
const key = (item) => [item.country_name, item.dashboard_name, item.card_name, item.metric_name, item.dimension_name, item.time_granularity].join('\u001f');
const action = String(raw.action || '').trim();
if (!actions.has(action)) throw new Error('action must be ensure, lookup, or update');
const inputItems = Array.isArray(raw.items) ? raw.items : [];
const items = [...new Map(inputItems.map(normalize).map((item) => [key(item), item])).values()];
const tableSql = `CREATE TABLE IF NOT EXISTS warning_rule.fluctuation_metric_tags (country_name CHAR(32) NOT NULL, dashboard_name CHAR(128) NOT NULL, card_name CHAR(128) NOT NULL, metric_name CHAR(128) NOT NULL, dimension_name CHAR(128) NOT NULL, time_granularity CHAR(8) NOT NULL, dashboard_url CHAR(255) NOT NULL DEFAULT '', tag CHAR(2) NOT NULL DEFAULT '二级', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, PRIMARY KEY (country_name, dashboard_name, card_name, metric_name, dimension_name, time_granularity)) DEFAULT CHARSET=utf8mb4`;
let query = 'SELECT 0 AS affectedRows';
if (action === 'ensure') {
  if (items.length > 0) {
    const values = items.map((item) => `(${[item.country_name, item.dashboard_name, item.card_name, item.metric_name, item.dimension_name, item.time_granularity, item.dashboard_url].map(quote).join(', ')}, '二级')`).join(', ');
    query = `INSERT INTO warning_rule.fluctuation_metric_tags (country_name, dashboard_name, card_name, metric_name, dimension_name, time_granularity, dashboard_url, tag) VALUES ${values} ON DUPLICATE KEY UPDATE dashboard_url = dashboard_url`;
  }
} else if (action === 'lookup') {
  if (items.length > 0) {
    const tuples = items.map((item) => `(${[item.country_name, item.dashboard_name, item.card_name, item.metric_name, item.dimension_name, item.time_granularity].map(quote).join(', ')})`).join(', ');
    query = `SELECT country_name, dashboard_name, card_name, metric_name, dimension_name, time_granularity, tag FROM warning_rule.fluctuation_metric_tags WHERE (country_name, dashboard_name, card_name, metric_name, dimension_name, time_granularity) IN (${tuples})`;
  }
} else {
  const identity = normalize(raw.identity);
  const tag = String(raw.tag || '').trim();
  if (!tags.has(tag)) throw new Error('tag must be 一级, 二级, or 三级');
  const values = [identity.country_name, identity.dashboard_name, identity.card_name, identity.metric_name, identity.dimension_name, identity.time_granularity, identity.dashboard_url, tag].map(quote).join(', ');
  query = `INSERT INTO warning_rule.fluctuation_metric_tags (country_name, dashboard_name, card_name, metric_name, dimension_name, time_granularity, dashboard_url, tag) VALUES (${values}) ON DUPLICATE KEY UPDATE tag = VALUES(tag), updated_at = CURRENT_TIMESTAMP`;
}
return [{ json: { action, items, query, tableSql } }];

const rows = $input.all().map((item) => item.json).filter((row) => row && row.country_name);
const key = (row) => [row.country_name, row.dashboard_name, row.card_name, row.metric_name, row.dimension_name, row.time_granularity].join('\u001f');
const tags = Object.fromEntries(rows.map((row) => [key(row), ['一级', '二级', '三级'].includes(row.tag) ? row.tag : '二级']));
return [{ json: { success: true, tags } }];

const request = $('Normalize Tag Request').first().json;
const result = $input.first()?.json || {};
return [{ json: { success: true, action: request.action, inserted: request.action === 'ensure' ? Number(result.affectedRows || request.items.length || 0) : undefined } }];
